// ignore_for_file: avoid_web_libraries_in_flutter, deprecated_member_use
import 'dart:html' as html;

/// Web background music & cheerful sound effects player for Collaborative Picnic Memory Game.
class PicnicBgmPlayer {
  html.AudioElement? _bgmAudio;
  bool _isMuted = false;
  bool _isPlaying = false;

  bool get isMuted => _isMuted;
  bool get isPlaying => _isPlaying;

  void startBgm() {
    if (_isMuted) return;
    try {
      _bgmAudio ??= html.AudioElement(_picnicBgmDataUri)
        ..loop = true
        ..volume = 0.12;
      _bgmAudio!.volume = 0.12;
      _bgmAudio!.play();
      _isPlaying = true;
    } catch (_) {}
  }

  void stopBgm() {
    try {
      _bgmAudio?.pause();
      if (_bgmAudio != null) {
        _bgmAudio!.currentTime = 0;
      }
      _isPlaying = false;
    } catch (_) {}
  }

  void setMuted(bool muted) {
    _isMuted = muted;
    if (muted) {
      stopBgm();
    } else {
      startBgm();
    }
  }

  void playTapChime({double volume = 0.80}) {
    if (_isMuted) return;
    try {
      final chime = html.AudioElement(_tapChimeDataUri)
        ..volume = volume.clamp(0.0, 1.0);
      chime.play();
    } catch (_) {}
  }

  void playVictoryChime({double volume = 0.88}) {
    if (_isMuted) return;
    try {
      // Gently pause background music so the joyful victory celebration rings out clearly!
      _bgmAudio?.pause();
      _isPlaying = false;
      final win = html.AudioElement(_victoryChimeDataUri)
        ..volume = volume.clamp(0.0, 1.0);
      win.play();
    } catch (_) {}
  }

  void dispose() {
    stopBgm();
    _bgmAudio = null;
  }
}

const String _picnicBgmDataUri = 'data:audio/wav;base64,';
const String _tapChimeDataUri = 'data:audio/wav;base64,';
const String _victoryChimeDataUri = 'data:audio/wav;base64,';
